+        "in", "on", "at", "to", "for", "of", "with", "by", "it", "its",
+        "this", "that", "from", "as", "be", "has", "have", "had", "not",
+        "do", "does", "did", "will", "would", "could", "should", "may",
+        "can", "so", "if", "then", "than", "too", "very", "just", "about"
+    };
